function sourceApplicabilityState(project) {
  const reasons = [];
  const authored = acceptedChanges(project, 2)
    .filter(change => ['COMPLETE', 'RECONCILE_SOURCE_SEARCH'].includes(change.operation)&&change.scope?.inputVersion===inputVersionForStage(project, 2)&&change.scope?.sourceSetVersion===project.job.CURRENT_SOURCE_SET_VERSION).at(-1);
  if (!authored) reasons.push('A current accepted Stage 02 authored search is required.');
  reasons.push(...acceptedResponseOwnershipIssues(project, 2));
  if (unresolvedHumanRequests(project, 2).length) reasons.push('Blocking human input remains unresolved.');
  if (openBlockers(project, 2).length) reasons.push('A current mandatory Stage 02 blocker remains open.');
  if (safe(project.projectData.executionFailures).some(row => Number(row.stage) === 2 && !row.invalidatedBy && !row.resolvedBy && upper(row.status || 'OPEN') !== 'RESOLVED')) reasons.push('An accepted Stage 02 execution failure remains unresolved.');
  const contracts = recordsForCurrentScope(project, 'sourceSearchContracts').filter(row => Number(row.stage) === 2);
  if (contracts.length !== 1) reasons.push('Exactly one current bounded source search contract is required.');
  const contract = contracts.length === 1 ? contracts[0] : null;
  let evidenceIds = [];
  if (contract) {
    const evidence = evaluateEvidenceContract(null, contract, null, project);
    evidenceIds = safe(evidence.evidenceIds);
    if(!evidence.sufficient)reasons.push('The current source search contract lacks preserved execution evidence: '+evidence.reasons.join(' '));
    reasons.push(...sourceSearchCapabilityState(project, contract).reasons);
  }
  const sources = recordsForCurrentScope(project, 'sources').filter(row => Number(row.stage) === 2);
  for (const source of sources) reasons.push(...schema.sourceClassificationIssues(recordFields(source)));
  const conflicts = recordsForCurrentScope(project, 'sourceConflicts').filter(row => Number(row.stage) === 2);
  if (conflicts.some(row => ['UNRESOLVED', 'BLOCKED', 'UNKNOWN', 'OPEN'].includes(upper(recordValue(row, 'RESOLUTION_STATUS'))))) reasons.push('A current external-source conflict remains unresolved.');
  // This installed owner must use current accepted author provenance, qualified
  // independent review, exact current target ID/hash pairs and mixed-finding
  // rules. It returns complete=false for missing, negative, stale or unknown
  // review support. It never evaluates a gate or recalculates the project.
  const review = globalThis.closedLoopWorkflowEngine.sourceSearchAdequacyState?.(project);
  if (!review?.complete) reasons.push(...(review?.reasons?.length ? review.reasons : ['A current independent search-adequacy review is required.']));
  return {
    determination: reasons.length ? 'UNDETERMINED' : sources.length ? 'APPLICABLE_SOURCES_ESTABLISHED' : 'NO_APPLICABLE_EXTERNAL_SOURCE',
    reasons: [...new Set(reasons)],
    authorChangeId: authored?.changeId || null,
    contractId: contract ? recordId(contract, 'sourceSearchContracts') : null,
    reviewId: review?.complete ? review.reviewId : null,
    sourceIds: sources.map(row => recordId(row, 'sources')),
    evidenceIds
  };
}

function acceptedResponseOwnershipIssues(project,stage){
  const issues=[];
  for(const change of acceptedChanges(project,stage)){
    const proposal=safe(project.projectData.responseProposals).find(item=>item.proposalId===change.proposalId);
    for(const [collection,rows] of Object.entries(proposal?.envelope?.records||{})){
      const currentIds=new Set(recordsForCurrentScope(project,collection).filter(record=>record.sourceProposalId===change.proposalId).map(record=>recordId(record,collection)));
      for(const row of safe(rows)){
        const id=String(row.targetId||proposal.tempToCanonical?.[row.tempKey]?.id||'');
        if(!currentIds.has(id))continue;
        for(const name of Object.keys(row.fields||{})){
          const producer=schema.RECORD_SCHEMAS[collection]?.fieldDefinitions?.[name]?.producer;
          if(producer===schema.PRODUCER.AGENT)continue;
          const owner=producer?String(producer).toLowerCase().replaceAll('_','-'):'unregistered';
          issues.push(`The accepted response assigned ${owner}-owned field ${collection}.${name}. Correct and replace that response; its original evidence remains preserved.`);
        }
      }
    }
  }
  return [...new Set(issues)];
}

function synchronizeStage01JobProjection(project){
  const data=project.stages[1]?.agentData||{};
  for(const name of schema.AGENT_JOB_FIELDS){
    if(Object.hasOwn(data,name))project.job[name]=clone(data[name]);
    else delete project.job[name];
  }
}

