function recalculate(project,options={}){return withReadinessEvaluationEpoch(()=>recalculateProjection(project,options));}
function recalculateProjection(project,{evaluateGate=gate,nextAction=operationalNextAction}={}){
  // Commands defined in this module must use the installed gate/continuation
  // owners too. A closed-over earlier gate must never restore false completion.
  const installed=globalThis.closedLoopWorkflowEngine;
  if(evaluateGate===gate&&installed?.gate)evaluateGate=installed.gate;
  if(nextAction===operationalNextAction&&installed?.operationalNextAction)nextAction=installed.operationalNextAction;
  ensureShape(project);
  for(const repair of jobPointerProjectionRepairs(project))project.job[repair.field]=repair.to;
  project.job.INPUT_SET_HASH_OR_MANIFEST=intakeCoverageManifest(project).manifestSha256;
  project.job.CURRENT_HASH_REVIEW_ID=deriveArtifactIdentity(project).value.HASH_REVIEW_ID||project.job.CURRENT_HASH_REVIEW_ID||null;
  // Reuse belongs only to the installed gate and continuation owners.
  // Caller-supplied callbacks may change adjudication inputs during traversal.
  const sharedProjection=evaluateGate===installed?.gate&&nextAction===installed?.operationalNextAction;
  const projectStages=()=>{
  let previousComplete=true;
  for(let stage=1;stage<=30;stage++){
    let state=project.stages[stage];
    if(!previousComplete&&!stageEntryState(project,stage,{allPrevious:false}).allowed){
      const prerequisite=`Stage ${String(stage-1).padStart(2,'0')} is not complete.`;
      state.status='NOT STARTED';
      state.gate={complete:false,blocked:false,reasons:[prerequisite]};
      state.decision='';
      state.decisionEvidence=prerequisite;
      state.derivedData={STAGE_DECISION:'NOT READY - CORRECTION REQUIRED',DECISION_EVIDENCE:prerequisite};
      continue;
    }
    const result=evaluateGate(stage,project);
    // gate() normalizes project shape and may replace stage objects; always mutate the current canonical object.
    state=project.stages[stage];
    state.gate=result;
    if(result.blocked){state.status='BLOCKED';}
    else if(result.complete){state.status='COMPLETE';}
    else if(hasStageActivity(project,stage)){state.status='IN PROGRESS';}
    else state.status='READY';
    state.decision=state.status==='COMPLETE'?'READY TO PROCEED':state.status==='BLOCKED'?'BLOCKED':'';
    state.decisionEvidence=result.reasons.length?result.reasons.join('; '):'Derived canonical stage gate satisfied.';
    const derivedData=deriveStageData(project,stage);
    project.stages[stage].derivedData=derivedData;
    previousComplete=project.stages[stage].status==='COMPLETE';
  }
  };
  // A receipt belongs only to this synchronous traversal. Each gate still
  // receives fresh mutable shells; exceptions discard every private receipt.
  if(sharedProjection)withCompletedStageAdjudications(project,()=>withInputScopeEvaluation(projectStages));
  else projectStages();
  const workflowComplete=workflowCompletionState(project);
  const currentStage=currentWorkflowStage(project);
  const current=project.stages[currentStage];
  project.activeStage=Math.max(1,Math.min(30,Number(project.activeStage||currentStage)));
  project.job.CURRENT_STAGE=`STAGE ${String(currentStage).padStart(2,'0')}`;
  const projectOpenBlockers=openBlockers(project);
  project.job.CURRENT_STATE=operationState(project,currentStage,workflowComplete);
  project.job.CURRENT_BLOCKERS=projectOpenBlockers.map(record=>recordId(record,'blockers'));
  // Passing every stage gate does not discharge a remaining terminal operation.
  // The installed continuation policy owns both progression and completion.
  project.job.NEXT_REQUIRED_ACTION=nextAction(project,currentStage);
  project.job.LATEST_EVIDENCE_REFERENCE=recordId(records(project,'evidenceRecords',{active:false}).at(-1),'evidenceRecords')||null;
  project.job.JOB_RECORD_STATUS=project.stages[1].status==='COMPLETE'?'COMPLETE':project.stages[1].status==='BLOCKED'?'BLOCKED':'INCOMPLETE';
  project.job.STATUS_EVIDENCE=project.stages[1].gate?.reasons?.join('; ')||'Stage 01 canonical evidence is complete.';
  return project;
}

